<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class FileView extends Model {public $timestamps=false; protected $fillable=['resource_file_id','resource_id','visitor_hash','session_id','user_id','ip_address','user_agent','created_at']; protected $casts=['created_at'=>'datetime']; public function file(){return $this->belongsTo(ResourceFile::class,'resource_file_id');} public function resource(){return $this->belongsTo(Resource::class);} }
